#!/usr/bin/env python3
"""Generates the website's document pages (privacy, terms, support, brand,
404) in website/.

Header, footer and the icon sprite are taken from website/index.html so every
page stays in sync with the home page. Edit the content below, then run:

    python3 website/scripts/generate-pages.py

Keep the privacy policy in step with the app: if a dependency starts sending
data off the device (analytics events, a new SDK, a network feature), this
policy and the Play Data safety / App Store privacy answers must change too.
"""
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent  # website/
SITE = 'https://quoai.vercel.app'
EMAIL = 'astralabsltd@gmail.com'
COMPANY = 'Astra Labs Ltd'
COMPANY_DETAILS = ('a company registered in England and Wales (company number 16558481), '
                   'registered office 82 James Carter Road, Mildenhall, IP28 7DE, United Kingdom')
UPDATED = '18 October 2026'

home = (ROOT / 'index.html').read_text()
SYMBOL = re.search(r'<svg width="0".*?</svg>', home, re.S).group(0)
HEADER = re.search(r'<header class="site-header">.*?</header>', home, re.S).group(0)
FOOTER = re.search(r'<footer class="site-footer">.*?</footer>', home, re.S).group(0)
MAIL = f'<a href="mailto:{EMAIL}">{EMAIL}</a>'


def page(title, desc, body, path, main='doc'):
    return f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<meta name="description" content="{desc}">
<meta name="theme-color" content="#3b2eff">
<link rel="canonical" href="{SITE}{path}">
<meta property="og:title" content="{title}">
<meta property="og:description" content="{desc}">
<meta property="og:image" content="{SITE}/assets/og.png">
<meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="/assets/favicon.png">
<link rel="apple-touch-icon" href="/assets/apple-touch-icon.png">
<link rel="stylesheet" href="/assets/site.css">
<script src="/assets/site.js" defer></script>
</head>
<body>
{SYMBOL}
{HEADER}
<main class="{main}">
{body}
</main>
{FOOTER}
</body>
</html>
'''


privacy = f'''<h1>Privacy Policy</h1>
<p class="meta">Last updated {UPDATED} · Applies to the Quo apps (phone, web and desktop) and this website</p>
<div class="summary"><p><strong>In short:</strong> Quo runs its AI on your device. Your conversations, files, photos, voice and memories are processed and stored only on your device and are never sent to us or anyone else, unless you choose the optional cloud model in Quo Web or the desktop app; those messages are sent to the model’s provider to answer, and nobody keeps them. If you choose to turn on Quo Sync (optional, and it needs a Quo account), your chats and memories are uploaded only after being encrypted on your device with a key we never receive, so we still can’t read them. To fix crashes and improve the app, Quo collects limited usage and crash data that never includes your content: in the EU and EEA only if you allow it, and anywhere you can turn it off at any time in Settings.</p></div>

<h2>Who we are</h2>
<p>Quo is made by {COMPANY} (“we”, “us”), {COMPANY_DETAILS}. We are the controller of the limited personal data described in this policy. For any privacy question or request, email {MAIL}.</p>

<h2>What stays on your device</h2>
<p>The following is processed on your device and is never sent to us or to any AI service in a form anyone can read:</p>
<ul>
<li>Your messages and the AI’s replies</li>
<li>Documents and photos you attach</li>
<li>Voice input, which is transcribed by a speech model running on your device</li>
<li>Memories (what the AI saves about you in the Android app, and what you add yourself in Quo Web and the desktop app), and your settings. Offline models read your memories; cloud models never receive them.</li>
</ul>
<p>Read-aloud uses your device’s built-in text-to-speech engine. You don’t need an account to use Quo. We cannot see, read or recover your conversations. That stays true if you use Quo Sync, described below, because what it uploads is encrypted on your device with a key only you hold.</p>

<h2>Information we collect</h2>
<h3>Usage and crash data</h3>
<p>Quo uses Google Firebase Analytics and Firebase Crashlytics to understand how the app is used and to fix problems. This collects:</p>
<ul>
<li><strong>App events</strong>, such as the app being opened, a model being downloaded or loaded, a chat being started, the upgrade screen being shown, and purchases (product, price and currency)</li>
<li><strong>Performance and error information</strong>, such as load times, short error codes and crash reports (the technical state of the app when it crashed)</li>
<li><strong>Device and app information</strong>, such as device model, operating system version, language and app version</li>
<li><strong>Pseudonymous identifiers</strong> generated by Firebase for your installation of the app (not your name, email or the advertising ID)</li>
<li><strong>Approximate location</strong> at country or region level, which Google derives from your IP address</li>
</ul>
<p>This data never includes the content of your chats, prompts, files, photos or voice. Error reports are reduced to short codes so they don’t contain your data.</p>
<p><strong>In the EU and EEA</strong>, Quo asks for your consent first and collects no usage or crash data unless you choose “Allow”. <strong>Elsewhere</strong>, collection is on by default. Wherever you are, you can change your choice at any time in <strong>Settings → Data → Share Usage Analytics</strong>, which turns both analytics and crash reporting on or off.</p>
<p>Quo does not use the advertising ID, does not show ads, does not track you across other apps or websites, and does not sell or share personal data for advertising.</p>
<h3>App configuration</h3>
<p>Quo downloads configuration values from Firebase Remote Config to adjust app behaviour. This request includes the app’s Firebase installation identifier and app version, and never your content. It happens only when usage data collection is allowed; otherwise Quo uses built-in defaults.</p>
<h3>When you contact us</h3>
<p>If you email us, we receive your email address and whatever you include in your message. We use it only to reply to you.</p>

<h2>Accounts and Quo Sync</h2>
<p>You only need a Quo account to use Quo Sync, which keeps your chats and memories in step between your devices (Quo Web, the desktop app and the Android app), or to buy Quo Pro or a Quo Sync plan. Everything else works without one.</p>
<h3>Your account</h3>
<p>You sign in with your email address: we email you a six-digit code (through our email provider, Resend), which works for 10 minutes. We keep your email address, a one-way hash of the code until it is used or replaced, and records of your plan and credits. Staying signed in uses a secure cookie (Quo Web and the desktop app) or a token held in your phone’s secure storage; signing out removes it from that device, and “sign out of all devices” ends every sign-in at once.</p>
<h3>What Quo Sync stores</h3>
<p>If you turn on Quo Sync, each chat and memory is encrypted on your device before it is uploaded, with a key made from a recovery key that you save and that we never receive. We store the encrypted data, a random identifier for each item, its size and when it last changed, and a small encrypted check value that lets a new device confirm your recovery key. The names of attached files are part of the encrypted data; the files, photos and models themselves are never synced.</p>
<p>We can’t read, search or recover your synced chats and memories, and if you lose your recovery key nobody can open them. We can tell that your account uses Quo Sync, roughly how many items it holds, how big they are and when they changed, but not what they say.</p>
<h3>Payments</h3>
<p>Quo Pro and Quo Sync plans bought on the web or in the desktop app are sold by Paddle, our merchant of record, which collects your payment details and handles tax. We receive your email address, your country and the status of your plan, never your card details.</p>
<h3>Deleting your account</h3>
<p>You can delete your account yourself at any time (<strong>Settings → Sync</strong> in the Android app, <strong>Plan &amp; credits</strong> in Quo Web and the desktop app; see <a href="/delete-account/">how to delete your account</a>), as long as you have no running plan; cancel that first. Deleting it removes your synced chats and memories, your credits and your plan records from our systems. The chats and memories on your devices stay. Paddle keeps its own records of purchases, as the law requires.</p>

<h2>Downloads and purchases</h2>
<p>AI models are downloaded from Hugging Face, a public model host, or, if you add a custom model, from the web address you enter. On Android, the starter model may instead be delivered by Google Play. As with any download, the host receives standard request information such as your IP address and is responsible for it under its own privacy policy.</p>
<p>The optional Premium upgrade is bought through Google Play or the App Store, which process your payment under their own privacy policies. We receive confirmation of the purchase (such as the product and its status), never your payment details.</p>

<h2>Notifications and permissions</h2>
<p>If you allow notifications, Quo shows notifications generated on your device (for example when a long reply finishes). Quo does not use a push notification service.</p>
<p>Quo asks for access to the microphone (voice input), camera and photos (to attach images) and files (to attach documents) only when you use those features. What they capture is processed on your device.</p>

<h2>This website</h2>
<p>This website uses no cookies, analytics or trackers. It is hosted by Vercel, which processes standard server logs (such as IP address, browser type and the pages requested) to deliver and secure the site.</p>

<h2>Quo Web and Quo for desktop</h2>
<p>With offline models, everything happens on your computer: your chats are saved only in your browser’s or the app’s storage on that computer, and nothing you type is sent anywhere. Models are downloaded once from Hugging Face, and the desktop app checks GitHub for updates; like any download, these requests show your IP address to those services.</p>
<p>Files you attach (PDFs, text files and photos) are read on your computer and only ever go to an offline model, never to the cloud model. Voice input turns your speech into text on your computer: the speech model (about 80 MB) is downloaded once from Hugging Face, and your audio is neither saved nor sent anywhere. Read aloud uses your system’s own voices. The desktop app runs the AI in a separate program on your computer (llama.cpp) that can only be reached from your own computer, with a key that only the app knows.</p>
<h3>Optional cloud model</h3>
<p>Quo Web and the desktop app also offer a free cloud model, clearly marked and used only when you pick it. When you do, the messages in that chat are sent through our server to OpenRouter, which passes them to the model’s provider (for example OpenAI) to write the reply. We only use providers that don’t keep or train on your messages, and our server doesn’t store them either.</p>
<p>In <strong>Code mode</strong> (desktop app, only when you turn it on and choose a project folder) with an offline model, nothing leaves your computer. With a paid cloud model, the files Quo reads from that folder, and the output of commands you approve, are sent to the model’s provider as part of the conversation, in the same way. Quo never reads secrets files (such as .env files and keys), changes a file or runs a command only after you confirm it in a window the page can’t click (apart from a few read-only checks, such as <code>git status</code>, that run on their own and can’t change anything), and has no internet access other than downloading public GitHub repositories you or the model ask to look at, and web search when it is on.</p>
<h3>Web search</h3>
<p>In the desktop app, models can search the web and read pages when <strong>Web</strong> is on. It is on by default with cloud models and your own API keys, and off with offline models until you turn it on, so an offline chat stays offline. When it is on, the words the model searches for go to the search service you chose (Brave Search, Tavily or Exa with your own key, a SearXNG address, or DuckDuckGo), and pages are fetched by your computer, not through our servers. Quo only opens addresses you wrote, that a search returned, or that a page it read links to, and never addresses on your own computer or network. Keys for search services are kept like other API keys. In a browser, web search is done by OpenRouter or Anthropic, if you use your own key with them.</p>
<h3>Your own API keys</h3>
<p>You can also use models with an API key of your own (from OpenRouter, Anthropic, OpenAI, Google, xAI, DeepSeek, Mistral, Groq, or a server you run yourself), with no Quo account. When you do, the messages in that chat, and in Code mode the files Quo reads, go <strong>straight from your computer to that provider</strong>, under that provider’s terms and privacy policy. They do not go through our servers, and we never see your key or your messages. In the desktop app your key is saved encrypted by your operating system’s secure storage (where it has none, it is kept in memory until you quit) and the app’s pages can never read it back; in a browser it is saved in that browser only. Keys are never synced and never sent to us. Memories and attached files are not sent to these models, as with our own cloud model.</p>
<p>To keep the free allowance fair, our server counts how many cloud messages are sent each day per device and per IP address. It stores these counts under one-way keyed hashes, never the IP address or the app’s random device ID itself, and deletes them after two days. There are no accounts on Quo Web yet.</p>

<h2>Why we use your data (legal bases)</h2>
<p>Where UK or EU data protection law applies, we rely on:</p>
<ul>
<li><strong>Consent</strong> for usage and crash data in the EU and EEA. You can withdraw it at any time in Settings.</li>
<li><strong>Legitimate interests</strong> for usage and crash data elsewhere, including the UK (keeping Quo working and improving it), for website logs (security) and for replying to emails. We keep this data minimal and pseudonymous, and you can switch off usage and crash data at any time.</li>
<li><strong>Performance of a contract</strong> to provide Premium after you buy it, to answer your messages when you choose a cloud model, and to sign you in and provide Quo Sync and your plan if you have an account.</li>
<li><strong>Legitimate interests</strong> for counting free cloud messages, to stop abuse of the free allowance.</li>
<li><strong>Legal obligations</strong>, for example keeping purchase and tax records.</li>
</ul>

<h2>Service providers and international transfers</h2>
<p>Google (Firebase), Vercel (hosting), Neon (our database, in London) and Resend (sign-in emails) process data for us as service providers, and Paddle sells Quo Pro and Quo Sync plans as merchant of record. When you choose a cloud model, OpenRouter and that model’s provider process those messages to answer them. They may process it outside the UK and EU, including in the United States. Where they do, the transfer is protected by recognised safeguards such as the EU–US Data Privacy Framework and its UK Extension, or Standard Contractual Clauses.</p>

<h2>How long we keep data</h2>
<ul>
<li><strong>Your content</strong> stays on your device until you delete it. You can delete individual chats, clear all chats or memories (in Settings in the Android app, or under Memories in Quo Web and the desktop app), or uninstall the app to remove everything.</li>
<li><strong>Usage data</strong> is kept by Google for no longer than 14 months.</li>
<li><strong>Crash reports</strong> are kept by Google for about 90 days.</li>
<li><strong>Emails</strong> are kept only as long as needed to help you.</li>
<li><strong>Website logs</strong> are kept briefly by Vercel under its retention policy.</li>
<li><strong>Cloud messages</strong> aren’t stored by us; OpenRouter and the providers we use don’t retain them.</li>
<li><strong>Free cloud message counts</strong> are deleted after two days.</li>
<li><strong>Your account</strong> (email address, plan and credit records) is kept until you delete it. A sign-in code stops working after 10 minutes.</li>
<li><strong>Quo Sync data</strong> is kept until you delete it or your account. If your plan ends, it stays for 180 days (you can still download it to your devices), we email you once 30 days before it is deleted, and then it is deleted for good. Records that tell your other devices a chat was deleted are removed after 90 days.</li>
</ul>

<h2>Security</h2>
<p>Your content is protected by your device’s own security and, unless you use Quo Sync, never leaves it. Quo Sync data is encrypted on your device (AES-256-GCM) before it is uploaded, and the key never leaves your devices. The limited data sent to our service providers is encrypted in transit.</p>

<h2>Children</h2>
<p>Quo is not directed at children under 13, and we do not knowingly collect personal data from them. If you believe a child has used Quo and data was collected, contact us and we will help.</p>

<h2>Your rights</h2>
<p>Depending on where you live, you may have the right to access, correct or delete your personal data, to restrict or object to its use, and to data portability. You can withdraw consent or object to usage and crash data at any time by turning it off in Settings. To make a request, email {MAIL}. If you have a Quo account you can delete it yourself, and everything we hold for it, as described above. For usage and crash data, which isn’t linked to an account, we may need information from your device (such as its analytics identifier) to find what’s linked to you.</p>
<p>If you are in the UK, you can complain to the Information Commissioner’s Office (ico.org.uk). If you are in the EU, you can complain to your local data protection authority. We would appreciate the chance to resolve your concern first.</p>
<h3>California residents</h3>
<p>In the past 12 months we have collected the categories described above: identifiers (pseudonymous app identifiers), internet or other electronic activity (app usage), approximate geolocation, and commercial information (purchase records). We use them only for the purposes in this policy. We do not sell or share personal information, as those terms are defined under California law, and we do not use sensitive personal information. You have the right to know, delete and correct your personal information, and we will not discriminate against you for exercising these rights.</p>

<h2>Changes</h2>
<p>We may update this policy. We will post the new version here with a new date, and tell you in the app if a change is significant.</p>

<h2>Contact</h2>
<p>{COMPANY}, 82 James Carter Road, Mildenhall, IP28 7DE, United Kingdom · {MAIL}</p>
'''

